python3 - <<'EOF'
import os, re, sys

root = "verl"
missing = {}  # module -> [importers]
all_files = []
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if not d.startswith(('.', '__pycache__'))]
    for fn in filenames:
        if fn.endswith(".py"):
            all_files.append(os.path.join(dirpath, fn))

def module_exists(mod):
    # mod like verl.models.registry
    parts = mod.split(".")
    p = os.path.join(*parts) + ".py"
    if os.path.exists(p):
        return True
    d = os.path.join(*parts)
    if os.path.isdir(d) and os.path.exists(os.path.join(d, "__init__.py")):
        return True
    return False

import_re = re.compile(r'^\s*(?:from|import)\s+(verl(?:\.[a-zA-Z0-9_]+)*)', re.M)
for f in all_files:
    try:
        src = open(f, errors="replace").read()
    except Exception:
        continue
    for m in import_re.finditer(src):
        mod = m.group(1)
        # check longest prefix that could be a module
        # try full, then trim trailing segments that might be attributes
        candidates = [mod]
        while "." in candidates[-1]:
            candidates.append(candidates[-1].rsplit(".", 1)[0])
        found = any(module_exists(c) for c in candidates)
        if not found:
            missing.setdefault(mod, []).append(f)

print(f"total py files: {len(all_files)}")
print("missing modules (referenced but not on disk):")
for mod in sorted(missing):
    importers = missing[mod]
    print(f"  {mod}   <- {len(importers)} importers; e.g. {importers[:4]}")
EOF

